export const CURRICULUM_DATA: Curriculum = { ...prePrimaryCurriculum, ...lowerPrimaryCurriculum };

export const getCurriculumByTerm = (grade: string, subject: string, terms: string[]): GradeCurriculum => {
    if (!grade || !subject) return {};

    const normalizedSubject = subject.toUpperCase()
        .replace(/ & /g, '_&_')
        .replace(/\s/g, '_')
        .replace('PRE-TECHNICAL_STUDIES', 'PRE-TECHNICAL_STUDIES'); 

    const lessonKey = `${grade.toUpperCase().replace(' ', '_')}_${normalizedSubject}_LESSON_BREAKDOWN`;
    const breakdownText = LESSON_BREAKDOWNS?.[lessonKey] || '';

    if (!breakdownText && grade && subject) {
        console.warn(`[Curriculum Safeguard] No curriculum data found for "${grade} - ${subject}". Generated key: "${lessonKey}"`);
    }

    if (!breakdownText) {
        return CURRICULUM_DATA[subject]?.[grade] || {};
    }

    const curriculum: GradeCurriculum = {};
    const processLine = (line: string) => {
        const strandMatch = line.match(/Strand:\s*([^,]+)/i);
        const subStrandMatch = line.match(/Sub-Strand:\s*([^,]+)/i);
        if (strandMatch && subStrandMatch) {
            const strand = toProperCase(strandMatch[1].trim());
            const subStrand = toProperCase(subStrandMatch[1].trim());
            if (!curriculum[strand]) curriculum[strand] = [];
            if (!curriculum[strand].includes(subStrand)) curriculum[strand].push(subStrand);
        }
    };

    const termHeaders: { index: number; terms: number[] }[] = [];
    const termRegex = /-{3,}\s*TERM\s+([\d,\s\wAND]+?)\s*-{3,}/gi;
    let match;
    while ((match = termRegex.exec(breakdownText)) !== null) {
        const termGroup = match[1] || '';
        const termsInHeader = new Set<number>();
        const termParts = termGroup.toUpperCase().split(/,|\s+AND\s+|\s+/).filter(Boolean);
        termParts.forEach(term => {
            if (term.includes('1') || term.includes('ONE') || term === 'I') termsInHeader.add(1);
            else if (term.includes('2') || term.includes('TWO') || term === 'II') termsInHeader.add(2);
            else if (term.includes('3') || term.includes('THREE') || term === 'III') termsInHeader.add(3);
        });
        if (termsInHeader.size > 0) termHeaders.push({ index: match.index, terms: Array.from(termsInHeader) });
    }
    termHeaders.sort((a, b) => a.index - b.index);

    let contentToProcess = '';
    let processedSomething = false;
    if (termHeaders.length > 0 && terms && terms.length > 0) {
        terms.forEach(selectedTerm => {
            const selectedNum = parseInt(selectedTerm.replace('Term ', ''));
            if (isNaN(selectedNum)) return;
            let bestHeader = termHeaders.find(h => h.terms.length === 1 && h.terms[0] === selectedNum);
            if (!bestHeader) bestHeader = termHeaders.find(h => h.terms.includes(selectedNum));
            if (bestHeader) {
                const startIndex = bestHeader.index;
                const nextHeaderIndex = termHeaders.findIndex(h => h.index > startIndex);
                const endIndex = nextHeaderIndex !== -1 ? termHeaders[nextHeaderIndex].index : breakdownText.length;
                contentToProcess += breakdownText.substring(startIndex, endIndex);
                processedSomething = true;
            }
        });
    }

    if (!processedSomething) contentToProcess = breakdownText;
    contentToProcess.split('\n').forEach(processLine);
    return curriculum;
};

import React, { useRef, useEffect, useState, useMemo } from 'react';
import { FormState, ContentType, QuestionType, QuestionDifficulty, ROWCLessonEntry } from '../types.ts';
