    const handleSubStrandChange = (strand: string, subStrand: string, isChecked: boolean) => {
        setFormState(prev => {
            const allSubStrandsForStrand = subjectCurriculum?.[strand] || [];
            const updatedTopics: { [strand: string]: string[] } = { ...(prev.multiSelectTopics || {}) };

            const currentSelection = (updatedTopics[strand]?.length === 0 && updatedTopics.hasOwnProperty(strand))
