                : (updatedTopics[strand] || []);

            let newSelection: string[];

            if (isChecked) {
                newSelection = [...new Set([...currentSelection, subStrand])];
            } else {
                newSelection = currentSelection.filter(ss => ss !== subStrand);
            }

            if (newSelection.length === 0) {
                delete updatedTopics[strand];
            } else if (allSubStrandsForStrand.length > 0 && newSelection.length === allSubStrandsForStrand.length) {
                updatedTopics[strand] = []; 
            } else {
                updatedTopics[strand] = newSelection.sort();
            }

            return { ...prev, multiSelectTopics: updatedTopics };
        });
    };

    const validateForm = (): boolean => {
        const newErrors: Record<string, string> = {};
        const { contentType, topic, topicInputMode, multiSelectTopics, distributionMode, totalQuestions, questionCounts, terms, rowcData, selectedLessons } = formState;

        if (!formState.grade) newErrors.grade = "Grade is required.";
        if (!formState.subject) newErrors.subject = "Subject is required.";

        const needsTopic = ![ContentType.SchemeOfWork, ContentType.TermExam, ContentType.RecordOfWorkCovered].includes(contentType);

        const hasSelectedLessons = isLessonPlan && selectedLessons && selectedLessons.length > 0;
