                     if (!lesson.lessonTitle.trim()) newErrors[`lesson_${index}_lessonTitle`] = 'Lesson Title required.';
                 });
             }
        }

        setErrors(newErrors);

        if (newErrors.questionCounts || newErrors.totalQuestions || newErrors.difficulty) {
            setActiveSection('assessment');
        } else if (newErrors.topic || newErrors.terms) {
            setActiveSection('topic');
        }

        return Object.keys(newErrors).length === 0;
    };

    const handleSubmitWithValidation = (e: React.FormEvent) => {
        e.preventDefault();
        if (isProcessingFile || isProcessingMarkingScheme) {
            alert("Please wait for the file to finish processing before generating content.");
            return;
        }
        if (validateForm()) {
            onSubmit(e);
        } else {
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }
    };


  const questionTypeLabels: { [key in QuestionType]?: string } = {
