                                </div>
                             ))}
                        </div>
                        <p className="text-red-500 text-xs pt-1 h-4">{errors.questionCounts || ''}</p>
                    </div>
                )}

                <div>
                    <div className="flex items-center justify-center w-full">
                        <label htmlFor="marking-scheme-upload" className={`flex flex-col items-center justify-center w-full h-24 border-2 border-gray-300 border-dashed rounded-lg cursor-pointer bg-gray-50 hover:bg-gray-100 transition-colors ${isProcessingMarkingScheme ? 'opacity-50 cursor-not-allowed' : ''}`}>
                            <div className="flex flex-col items-center justify-center pt-5 pb-6">
                                {isProcessingMarkingScheme ? (
                                     <p className="text-xs text-gray-500">Processing...</p>
                                ) : (
                                    <p className="text-xs text-gray-500">Upload Marking Scheme</p>
                                )}
                            </div>
                            <input id="marking-scheme-upload" type="file" className="hidden" onChange={(e) => handleFileChange(e, 'markingSchemeFile')} ref={markingSchemeFileInputRef} accept=".txt,.pdf,.doc,.docx,.jpg,.jpeg,.png" disabled={isProcessingMarkingScheme} />
                        </label>
                    </div>
                    {formState.markingSchemeFile && (
                        <div className="mt-2 flex items-center justify-between p-2 bg-gray-100 rounded-md">
                             <span className="text-sm text-gray-700 truncate">{formState.markingSchemeFile.name}</span>
                             <button type="button" onClick={() => { setFormState(s => ({...s, markingSchemeFile: undefined, markingSchemeText: '', markingSchemeImageBase64: undefined})); if(markingSchemeFileInputRef.current) markingSchemeFileInputRef.current.value=''; }} className="text-gray-500"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" /></svg></button>
                        </div>
                    )}
                </div>
               </div>
            )}

            {activeSection === 'customization' && (
                <div className="space-y-6">
                     <div>
                        <textarea id="additionalInstructions" name="additionalInstructions" value={formState.additionalInstructions} onChange={handleChange} rows={3} className="mt-1 block w-full shadow-sm sm:text-sm bg-white border-gray-300 rounded-md text-black" placeholder="Specific AI instructions..."></textarea>
                    </div>
                </div>
            )}
          </div>
        </div>
      )}

      <div className="mt-8 bg-white dark:bg-slate-800 border-t border-gray-200 p-4 rounded-b-xl shadow-inner">
          <div className="flex items-center justify-between">
              {!isRowcType && <button type="button" onClick={onStartNew} className="text-sm text-white underline">Reset Form</button>}
              <button type="submit" disabled={isLoading || isProcessingFile || isProcessingMarkingScheme} className="ml-auto inline-flex justify-center py-2.5 px-6 border border-transparent shadow-sm text-sm font-medium rounded-lg text-white bg-blue-700 hover:bg-blue-800 transition-all">
                {isLoading ? "Generating..." : "Generate Content"}
              </button>
          </div>
      </div>
    </form>
  );
};

