import React, { ErrorInfo, ReactNode, Component } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import { MemoryRouter } from 'react-router-dom';
import { ThemeProvider } from './hooks/useTheme';

console.log("🏫 Initializing Exameno ECG Application...");

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: any;
  errorInfo: any;
}

// FIX: GlobalErrorBoundary must be a React class component to use state and props. It has been updated to extend `Component` to resolve errors related to missing `setState` and `props` properties.
class GlobalErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = {
    hasError: false,
    error: null,
    errorInfo: null,
  };

  static getDerivedStateFromError(error: any): Partial<ErrorBoundaryState> {
    return { hasError: true, error: error };
  }

  componentDidCatch(error: any, errorInfo: ErrorInfo) {
    console.error("CRITICAL: Component Tree Error Caught", error, errorInfo);
    this.setState({ errorInfo });
  }

  handleReset = () => {
    try {
      localStorage.clear();
      window.location.reload();
    } catch (e) {
      window.location.href = window.location.origin;
    }
  };

  render() {
    if (this.state.hasError) {
      return (
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          minHeight: '100vh',
          backgroundColor: '#011410',
          color: 'white',
          fontFamily: 'system-ui, sans-serif',
          padding: '2rem',
          textAlign: 'center'
        }}>
          <div style={{ background: '#011a15', padding: '2rem', borderRadius: '1rem', border: '1px solid #022c22', maxWidth: '800px', width: '100%' }}>
            <h1 style={{ color: '#10b981', fontSize: '1.8rem', marginBottom: '1rem' }}>Application Encountered an Error</h1>
            <p style={{ color: '#34d399', marginBottom: '1.5rem' }}>This usually happens if saved data becomes incompatible. Resetting the app usually fixes it.</p>

            <div style={{ textAlign: 'left', marginBottom: '1.5rem' }}>
              <pre style={{
                backgroundColor: 'rgba(0,0,0,0.4)',
                padding: '1rem',
                borderRadius: '0.5rem',
                overflow: 'auto',
                fontSize: '0.75rem',
                fontFamily: 'monospace',
                border: '1px solid #022c22',
                color: '#a7f3d0',
                maxHeight: '300px'
              }}>
                {this.state.error?.toString()}
                {this.state.errorInfo?.componentStack}
              </pre>
            </div>

            <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center' }}>
              <button 
                onClick={() => window.location.reload()}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: '#022c22',
                  color: 'white',
                  border: '1px solid #10b981',
                  borderRadius: '0.5rem',
                  cursor: 'pointer',
                  fontWeight: 'bold'
                }}
              >
                Reload App
              </button>
              <button 
                onClick={this.handleReset}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: '#047857',
                  color: 'white',
                  border: 'none',
                  borderRadius: '0.5rem',
                  cursor: 'pointer',
                  fontWeight: 'bold'
                }}
              >
                Reset Data & Clear Cache
              </button>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children || null;
  }
}

const container = document.getElementById('root');
if (container) {
  const root = createRoot(container);
  root.render(
    <GlobalErrorBoundary>
      <MemoryRouter>
        <ThemeProvider>
          <App />
        </ThemeProvider>
      </MemoryRouter>
    </GlobalErrorBoundary>
  );
} else {
    console.error("Root element not found");
}

import { GoogleGenAI, Type } from "@google/genai";
import { FormState, ContentType, GeneratedContent, QuestionType, RawMCQ, GeneratedQuestion, RawQuestion, SchemeOfWorkData, ROWCFormData, RawShortAnswer, RawTrueFalse, RawEssay, RawDiscussion, SchemeOfWorkEntry } from '../types.ts';
import { processMCQ, getDocumentTitle } from '../utils/quizProcessor.ts';
import { LESSON_BREAKDOWNS } from '../data/curriculum/index.ts';

const FAILED_IMAGE_PLACEHOLDER = 'data:image/svg+xml;base64,';

const PRO_MODEL = 'gemini-3-pro-preview';
const FLASH_MODEL = 'gemini-3-flash-preview';
const IMAGE_FLASH = 'gemini-2.5-flash-image';
const IMAGE_PRO = 'gemini-3-pro-image-preview';

const SOW_EXPECTED_WEEKS = 13;
const SOW_LESSONS_PER_WEEK = 5;

const getAI = () => {
    // Guideline: Initialize with new GoogleGenAI({apiKey: process.env.API_KEY}) directly
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const isKiswahili = (subject: string) => subject && subject.toLowerCase().includes('kiswahili');

export async function generateImage(prompt: string, subject: string, metadata: { grade: string }, isForQuestion: boolean = false, imageSize: '1K' | '2K' | '4K' = '1K', aspectRatio?: string): Promise<string> {
    try {
        const fullPrompt = `An educational illustration for a Kenyan Competency-Based Curriculum (CBC) ${metadata.grade} ${subject} class. The style should be clean, simple, colorful, and culturally relevant to Kenyan learners. 
        CRITICAL: Background MUST be solid, plain white. DO NOT use patterns or gradients.
        ${isForQuestion 
            ? "Pedagogical Note: This image is a visual aid for an assessment. 1. Label parts clearly with letters (A, B, C) if the question refers to them. 2. DO NOT include the names of parts in the image itself to avoid giving away the answer." 
            : ""} 
        Content to illustrate: ${prompt}`;

        const isHighQuality = imageSize === '2K' || imageSize === '4K';
        const modelName = isHighQuality ? IMAGE_PRO : IMAGE_FLASH;

        if (isHighQuality && typeof window !== 'undefined' && (window as any).aistudio) {
             const aistudio = (window as any).aistudio;
             if (!await aistudio.hasSelectedApiKey()) {
                 await aistudio.openSelectKey();
             }
        }

        // Guideline: Create a new GoogleGenAI instance right before making an API call to use the latest API key
        const ai = getAI();
        const response = await ai.models.generateContent({
            model: modelName,
            contents: { parts: [{ text: fullPrompt }] },
            config: {
                imageConfig: {
                    aspectRatio: aspectRatio || "1:1",
                    imageSize: isHighQuality ? imageSize : undefined
                }
            },
        });

        for (const part of response.candidates[0].content.parts) {
            // Find the image part as per nano banana series guidelines
            if (part.inlineData) {
                return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
            }
        }
        throw new Error("No image data found.");

    } catch (error: any) {
        console.error("Image generation failed:", error);
        if (error.message?.includes("Requested entity was not found.") && typeof window !== 'undefined' && (window as any).aistudio) {
             (window as any).aistudio.openSelectKey();
        }
        return FAILED_IMAGE_PLACEHOLDER;
    }
}

export async function generateSingleImageForQuestion(
  q: GeneratedQuestion,
  metadata: { grade: string; subject: string },
  imageSize: '1K' | '2K' | '4K' = '1K'
): Promise<{ imageUrl: string; imageDescription: string }> {
  const description = q.imageDescription || q.questionText;
  if (!description) return { imageUrl: '', imageDescription: '' };
  const imageUrl = await generateImage(description, metadata.subject, { grade: metadata.grade }, true, imageSize);
  return { imageUrl, imageDescription: description };
}

