        - The ENTIRE generated output (Headings, Subheadings, Bullet points, Content, Questions, Answers) MUST be in **KISWAHILI ONLY**.
        - Do not use English headers like "Introduction" or "Conclusion"; use their Kiswahili equivalents (e.g., "Utangulizi", "Hitimisho").
        - Maintain professional Markdown formatting.
        `;
    }

    const responseSchema = {
        type: Type.OBJECT,
        properties: {
            body: { type: Type.STRING },
            imagePrompts: {
                type: Type.ARRAY,
                items: {
                    type: Type.OBJECT,
                    properties: { placeholder: { type: Type.STRING }, prompt: { type: Type.STRING } }
                }
            }
        },
        required: ["body"]
    };

    const result = await ai.models.generateContent({
        model: FLASH_MODEL,
        contents: prompt + kiswahiliInstruction,
        config: { 
            systemInstruction: effectiveSystemInstruction, 
            responseMimeType: 'application/json',
            responseSchema: responseSchema
        },
    });

    const responseJson = JSON.parse(result.text || '{"body": "Failed."}');
    return {
        id: `gen_${Date.now()}`,
        title: getDocumentTitle({ metadata: { grade, subject, contentType, topic } } as GeneratedContent),
        body: responseJson.body,
        imagePrompts: responseJson.imagePrompts,
        metadata: { grade, subject, topic, contentType, imageSize },
    };
}

export async function generateContent(formState: FormState, teacherName?: string, schoolName?: string): Promise<GeneratedContent> {
    const systemInstruction = `You are a Senior Curriculum Developer and Master Teacher in the Kenyan Education System (CBC Experts).`;

    try {
        switch (formState.contentType) {
            case ContentType.Assessment:
            case ContentType.Quiz:
            case ContentType.TopicExam:
            case ContentType.TermExam:
                return await generateAssessment(formState, systemInstruction);
            case ContentType.SchemeOfWork:
                return await generateSchemeOfWork(formState, teacherName, systemInstruction);
            case ContentType.RecordOfWorkCovered:
                return await generateROWC(formState, systemInstruction);
            default:
                return await generateTextContent(formState, systemInstruction, teacherName, schoolName);
        }
    } catch (e: any) {
        console.error("AI Generation failed:", e);
        throw new Error(e.message || "Content generation failed.");
    }
}

export async function auditCurriculumAlignment(content: GeneratedContent): Promise<string> {
  const ai = getAI();
  const { grade, subject } = content.metadata || {};
  const result = await ai.models.generateContent({
    model: PRO_MODEL,
    contents: `Critique this educational content against the official Kenyan CBC standards for ${grade} ${subject}.\n\nCONTENT:\n${content.body || JSON.stringify(content.questions)}`,
    config: { systemInstruction: "You are a lead curriculum auditor at KICD." }
  });
  return result.text || "Audit failed.";
}

export async function summarizeContent(content: GeneratedContent): Promise<string> {
    const ai = getAI();
    const result = await ai.models.generateContent({
        model: FLASH_MODEL,
        contents: `Provide an Executive Summary: ${content.body || JSON.stringify(content.questions)}`,
        config: { systemInstruction: "Provide a 3-bullet summary with 'Key Takeaways'." }
    });
    return result.text || "Summary failed.";
}

export async function generateRubric(content: GeneratedContent): Promise<string> {
  const ai = getAI();
  const result = await ai.models.generateContent({
    model: PRO_MODEL,
    contents: `Create a detailed CBC assessment rubric for: ${content.title}. The rubric should be a Markdown table.`,
    config: { systemInstruction: "You are an expert educational assessor. Output the rubric as a clear Markdown table." }
  });
  return result.text || "Rubric generation failed.";
}

export async function applyAISuggestion(
  content: GeneratedContent,
  suggestionType: 'BLOOMS_TAXONOMY' | 'LEARNING_OUTCOMES' | 'IMPROVE_QUESTIONS'
): Promise<GeneratedContent> {
  const ai = getAI();
  let prompt = `Improve this content: ${suggestionType}`;

  const result = await ai.models.generateContent({
    model: FLASH_MODEL,
    contents: prompt
  });

  return { ...content, body: result.text || content.body };
}

export async function regenerateTextSection(sectionText: string, context: string): Promise<string> {
    const ai = getAI();
    const result = await ai.models.generateContent({
        model: FLASH_MODEL,
        contents: `Rewrite this section:\n"${sectionText}"\n\nContext: ${context.substring(0, 1000)}`
    });
    return result.text || sectionText;
}

export async function regenerateQuestion(question: GeneratedQuestion, context: string): Promise<GeneratedQuestion> {
    const ai = getAI();
    const result = await ai.models.generateContent({
        model: FLASH_MODEL,
        contents: `Replace this question: ${JSON.stringify(question)}`,
        config: { 
            responseMimeType: 'application/json',
            responseSchema: {
                type: Type.OBJECT,
                properties: { questionText: { type: Type.STRING }, correctAnswer: { type: Type.STRING }, explanation: { type: Type.STRING } }
            }
        }
    });
    const raw = JSON.parse(result.text || '{}');
    return { ...question, ...raw };
}

export async function generateAnalyticsInsights(logs: any[]): Promise<string> {
    const ai = getAI();
    const result = await ai.models.generateContent({
        model: PRO_MODEL,
        contents: `Analyze these usage logs: ${JSON.stringify(logs.slice(0, 30))}`,
        config: { systemInstruction: "You are a senior data analyst." }
    });
    return result.text || "No insights available.";
}

export async function getAIChat(content: GeneratedContent): Promise<any> {
    const ai = getAI();
    return ai.chats.create({
        model: FLASH_MODEL,
        config: { systemInstruction: `You are an expert consultant for: ${content.title}.` }
    });
}

